//	slug: The Team slug to perform the request on behalf of.
func GetProjectTrace(ctx context.Context, clientConfig ClientConfig, params GetProjectTraceParams, opts ...RequestOption) (*GetProjectTraceResponse, error) {
	projectId := params.ProjectId
	requestId := params.RequestId
	teamId := params.TeamId
	slug := params.Slug

	if err := ValidateLength("projectId", projectId, LengthOpts{Max: Ptr[int](150)}); err != nil {
		return nil, err
	}

	if err := ValidateLength("requestId", requestId, LengthOpts{Max: Ptr[int](256)}); err != nil {
		return nil, err
	}

	resp, err := DoCfg[GetProjectTraceResponse](ctx, &clientConfig, "GET", "/v1/projects/traces", &RequestOpts{
		Query: map[string]any{
			"projectId": QueryValue{Value: projectId, Style: "form", Explode: true},
			"requestId": QueryValue{Value: requestId, Style: "form", Explode: true},
			"teamId":    QueryValue{Value: teamId, Style: "form", Explode: true},
			"slug":      QueryValue{Value: slug, Style: "form", Explode: true},
		},
		OperationID: "GetProjectTrace",
		Options:     opts,
	})
	if err != nil {
		return nil, err
	}
	return &resp.Data, nil
}

